tool_calls:
cd /home/eval/pkgs && export LC_ALL=C && cat > /tmp/verify.awk <<'EOF'
# verify.awk <depsfile> <orderfile>: checks order validity + determinism rule
NR == FNR {
    line = $0; sub(/#.*/, "", line)
    if (line ~ /^[[:space:]]*$/) next
    c = index(line, ":")
    pkg = substr(line, 1, c-1); rest = substr(line, c+1)
    gsub(/^[[:space:]]+|[[:space:]]+$/, "", pkg)
    if (pkg == "") next
    allpkgs[pkg] = 1
    m = split(rest, f, /[[:space:]]+/)
    for (i=1;i<=m;i++) if (f[i] != "") { allpkgs[f[i]] = 1; isdep[pkg, f[i]] = 1 }
    next
}
{ ord[++k] = $1; pos[$1] = k }
END {
    # 1) every ordered package emitted exactly once
    for (p in pos) cnt[p]++
    for (p in pos) if (cnt[p] != 1) print "ERROR dup: " p
    # 2) deps emitted earlier
    bad = 0
    for (pd in isdep) {
        split(pd, x, SUBSEP)
        if (pos[x[1]] <= pos[x[2]]) { print "ERROR order: " x[2] " must precede " x[1]; bad = 1 }
    }
    # 3) each emitted package was the smallest available at its step
    for (p in allpkgs) done[p] = 0
    for (step = 1; step <= k; step++) {
        got = ord[step]; avail_min = ""
        for (p in allpkgs) {
            if (done[p]) continue
            ok = 1
            for (pd in isdep) { split(pd, x, SUBSEP); if (x[1] == p && !done[x[2]]) { ok = 0; break } }
            if (ok && (avail_min == "" || p < avail_min)) avail_min = p
        }
        if (got != avail_min) { print "ERROR step " step ": got " got " want " avail_min; bad = 1 }
        done[got] = 1
    }
    # 4) report packages never emitted
    for (p in allpkgs) if (!done[p]) print "UNEMITTED: " p
    if (!bad) print "VERIFY OK"
}
EOF
awk -f /tmp/verify.awk deps.txt build/order.txt && echo "===" && awk -f /tmp/verify.awk deps-big.txt build/big-order.txt

